build(ch, "heat-light", "Heat transfer, mirrors and light", 35,
      ["Name the three ways in which heat moves.", "Say how a mirror reflects light.", "Say what happens when white light passes through water drops."],
      [("key", "definition", "Heat transfer", "**Conduction**: heat passes through **solids**, especially metals (a metal spoon in hot soup). **Convection**: heat moves in **liquids and gases** because warm liquid or air **rises** and cool liquid or air sinks (boiling water, a rising smoke). **Radiation**: heat travels from the **Sun** through empty space. **Insulators** such as wood, plastic, air and wool slow down heat flow."),
       ("fig", fig, "How heat moves.", "A table with conduction in solids, convection in liquids and gases, and radiation through space, with examples."),
       ("key", "definition", "Reflection and colours", "A **mirror reflects** light: the angle at which light **hits** the mirror equals the angle at which it **bounces off**. **White light** is a mixture of colours: a **rainbow** forms when sunlight passes through raindrops and splits into the colours red, orange, yellow, green, blue, indigo and violet."),
       ("fig", fig2, "Light reflecting from a mirror.", "A flat mirror at the bottom. A ray comes down from the upper left and bounces up to the upper right at the same angle on the other side of the normal line."),
       ("key", "pieges", "Common mistakes", "- Saying that cold flows into a thing: heat flows **out** of hot things.\n- Thinking that a woollen jumper makes heat: it keeps in the body's heat.\n- Looking at the Sun or reflecting sunlight into someone's eyes.\n- Thinking that the rainbow is an object: it is an effect of light and water.")],
      [("ex", "Example 1", "Why does a metal spoon get hot at the end when it stands in a hot pot?", ["Metals conduct heat well.", "Heat passes along the spoon from the hot soup to the handle."], "By conduction.", None),
       ("ex", "Example 2", "A ray of light hits a mirror at an angle of 40° to the normal. What is the angle of the reflected ray?", ["The angle of reflection equals the angle of incidence.", "So the reflected ray makes 40° with the normal."], "40°", fig2)],
      [M("application", "How does heat travel from the Sun to the Earth?", "radiation", ["conduction", "convection", "reflection"], "Through space."),
       M("application", "Which is a good insulator?", "wool", ["copper", "iron", "aluminium"], "It traps air."),
       N("application", "The angle of incidence of a ray is 35° to the normal. What is the angle of the reflected ray?", 35, "They are equal.", unit="°"),
       TF("approfondissement", "Warm air rises.", True, "This is convection."),
       MA("approfondissement", "Match each example with the way heat moves.", [("a metal spoon in a hot pot", "conduction"), ("warm air rising from a fire", "convection"), ("heat from the Sun", "radiation"), ("a wool blanket", "insulation")], "Think about the material."),
       P("In a kitchen in Garoua, a pot of water boils on a fire. The metal handle is too hot to touch and warm air rises above the pot.",
         [PM("Why is the handle hot?", "metal conducts heat", ["metal radiates cold", "air is cold", "water is hot only"], "Conduction along the metal."),
          PM("What moves the warm air upward?", "convection", ["conduction", "reflection", "magnetism"], "Warm air rises."),
          PM("How can the cook hold the pot safely?", "use a cloth or an insulating handle", ["use bare hands", "pour water on it", "use a metal spoon"], "Insulators protect the hand.", points=2)])],
      [("Heat moves through solids by...", "conduction", ["convection", "radiation", "reflection"], "Metals are good conductors."),
       ("In reflection, the angle of incidence...", "equals the angle of reflection", ["is double it", "is smaller always", "is not related"], "Law of reflection."),
       ("A rainbow shows that white light is...", "a mixture of colours", ["only red", "dark", "a sound"], "It splits into colours."),
       ("A good insulator is...", "wood", ["copper", "iron", "silver"], "It slows heat flow."),
       ("Warm air...", "rises", ["sinks always", "turns into water", "stays still"], "It is lighter than cool air.")],
      ["Light and heat statements are standard; angle values are invented examples."])

